-- challenge chal_quiz_py_rag_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_py_rag_211', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-2-1' AND is_deleted = false LIMIT 1), 'bm25-parameters-quiz', 'What do k1 and b do?', 'Predict how BM25 treats repeated words and long documents before you implement it.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211'), 'Two help articles both mention "refund" twice. Article A has 60 words, article B has 600 words; the corpus average is 150 words. With the default b = 0.75, how does BM25 score the term "refund" for them?', 'single_choice'::question_type, 'b controls length normalisation. The denominator of the term-frequency part grows with |D| / avgdl, so the same two occurrences are worth more in the short article (60 / 150 = 0.4) than in the long one (600 / 150 = 4): in a short text, two mentions say much more about what it is about. With b = 0 both would score the same; with b = 1 the length effect is at its strongest.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('Equally: BM25 only counts occurrences.', false),
        ('Higher for A: the same occurrences count for more in a shorter document.', true),
        ('Higher for B: longer documents are more likely to be thorough.', false),
        ('It depends on k1 only; b affects the IDF.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211'), 'Which statements about BM25 are true? (Select all that apply.)', 'multiple_choice'::question_type, 'The term-frequency part f * (k1 + 1) / (f + k1 * ...) saturates: it grows quickly for the first occurrences and flattens towards k1 + 1, so the tenth occurrence adds far less than the second - keyword stuffing stops paying off. With k1 = 0 the part is f / f = 1 for any f > 0, so a term only counts by presence. With the +1 inside the logarithm, IDF stays positive even for a term found in every document, and a query term found in no document never contributes because f = 0 everywhere. Doubling a document''s length lowers, not raises, its score for the same occurrences.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The tenth occurrence of a term adds less to the score than the second.', true),
        ('With k1 = 0, a term contributes only by being present, however often it appears.', true),
        ('A query term that appears in every document gets a negative IDF.', false),
        ('Doubling a document''s length (same occurrences) doubles its score.', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_py_rag_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_py_rag_212', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-2-1' AND is_deleted = false LIMIT 1), 'bm25-ranker', 'Write bm25_rank(docs, query, k)', 'Replace the raw TF-IDF ranking with Okapi BM25: IDF(t) = ln((N - n(t) + 0.5) / (n(t) + 0.5) + 1), and a term-frequency part f * (k1 + 1) / (f + k1 * (1 - b + b * |D| / avgdl)) that saturates and normalises for length. Each distinct query term counts once. Return the top k documents with a score > 0 as [[id, score], ...], best first, scores rounded to 4 decimals at the end; equal scores keep the corpus order. Honour k1 and b when given (defaults 1.5 and 0.75), and return [] for an empty corpus or query.', 'open', 'hard'::difficulty_question, 'mini_coding', 30, true, false)
