-- challenge chal_quiz_py_rag_312 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_py_rag_312', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-3-1' AND is_deleted = false LIMIT 1), 'prompt-budget-and-t-strings-quiz', 'Budgets and t-string templates', 'Check how the context budget is computed and what Python 3.14 template strings give you.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_312'), 'The model has a 16,000-token context window. Which of these must be subtracted from it before you know how many tokens the retrieved chunks may use? (Select all that apply.)', 'multiple_choice'::question_type, 'Everything the model reads or writes in one call shares the window: the system prompt, the user''s question (and any conversation history you send), the formatting around the chunks, and the tokens the answer will need - if you do not reserve them, the API either rejects the request or cuts the answer short. The size of the index is irrelevant: only the chunks you actually put in the prompt count.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_312') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('The system prompt and instructions.', true),
        ('The user''s question and the conversation history you send.', true),
        ('Tokens reserved for the model''s answer.', true),
        ('The number of chunks stored in the vector index.', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_312'), 'In Python 3.14, what is the value of prompt after

prompt = t"<context>\n{context}\n</context>\nQuestion: {question}"', 'single_choice'::question_type, 'A t-string (PEP 750) evaluates its expressions like an f-string, but does not join the result into a str. It returns a string.templatelib.Template: iterating it yields the static strings and Interpolation objects (value, expression, conversion, format_spec), and .interpolations lists the values. Code that renders the template decides how each value is inserted - for a prompt, for example, by neutralising a retrieved chunk that contains "</context>" so it cannot close the block early.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_py_rag_312') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('A str with context and question already substituted, like an f-string.', false),
        ('A string.templatelib.Template holding the static text and Interpolation objects, to be rendered by your own code.', true),
        ('A lazy f-string that is rendered the first time it is converted with str().', false),
        ('A SyntaxError: the t prefix is only valid for bytes literals.', false)
    ) AS o(option_text, is_correct);

