-- challenge chal_fix_py_rag_321 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_fix_py_rag_321', (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-rag-from-scratch') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-py-rag-3-2' AND is_deleted = false LIMIT 1), 'retrieval-metrics', 'Fix the retrieval metrics', 'evaluate() computes recall@k, MRR@k and hit rate@k over a golden set, and the numbers cannot be trusted: recall changes with k even when nothing new is found, a document ranked 20th improves MRR@5, returning the same document twice raises recall, and unlabelled queries drag every average down. Fix it so that, per query with relevant ids, the top-k is the first k retrieved ids as returned, recall = relevant ids found / relevant ids (each counted once), MRR = 1 / rank of the first relevant id within the top-k, and hit = any relevant id in the top-k. Average over labelled queries only (0.0 when there are none), rounded to 4 decimals.', 'open', 'medium'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
